from pathlib import Path
p=Path('/tmp/parity-price.mjs');s=p.read_text();anchor="async function configure(service,plan,region)"
extra="""
plans['rds-oracle']={url:'amazonRDSOracle',profile:'standard',fields:[['input-profile--nodes','Nodes',1,2],['input-profile--utilizationPct','Utilization (On-Demand only) Value',100,50],['input-component-storage-gp3-gbMonths','Storage amount Value',100,200],['input-component-backup-storage-additionalGbMonths','Additional backup storage Value',10,20]],setup:async()=>{await choose('Storage for each RDS instance','General Purpose SSD (gp3)');await choose('Would you be enabling Database Insights','No');const combo=aws.locator('input[role="combobox"]:visible').first();await combo.fill('db.m3.2xlarge');await aws.getByRole('option').filter({hasText:'db.m3.2xlarge'}).first().click();}};
plans.redshift={url:'redshift',profile:'provisioned',fields:[['input-component-node-compute-nodes','Nodes',1,2],['input-component-node-compute-utilization','Utilization (On-Demand only) Value',100,50],['input-component-backup-tiered-backupGb','Additional backup storage Value',100,200],['input-component-spectrum-scannedTb','Data scanned Value',1,2],['input-component-rms-provisioned-managedGb','Managed storage size Value',0,100],['input-profile--transferInGb','Data Transfer In To Value',0,100]]};
plans.glue={url:'glue',profile:'standard',fields:[],setup:async()=>{await choose('Glue version','Glue version 6.0 and above',0);await choose('Glue version','Glue version 6.0 and above',1);await inputAws('Number of DPUs for Python Shell job Enter amount',0.0625);await inputAws('Duration for which Python Shell job ETL runs Value',0);},sync:async()=>{for(const [component,label]of [['etl-standard','Duration for which Apache Spark ETL job  runs Value'],['interactive-standard','Duration for provisioned interactive sessions Value']]){const runs=await local.locator('#input-component-'+component+'-runsPerMonth').inputValue(),minutes=await local.locator('#input-component-'+component+'-averageDurationMinutes').inputValue();await inputAws(label,new Decimal(runs).times(minutes).toString());}}};
for(const [component,dpu,duration]of [['etl-standard','Number of DPUs for Apache Spark job Enter amount','Duration for which Apache Spark ETL job  runs Value'],['interactive-standard','Number of DPUs for each provisioned interactive session Enter amount','Duration for provisioned interactive sessions Value']]){plans.glue.fields.push(['input-component-'+component+'-runsPerMonth','SKIP',10,20],['input-component-'+component+'-dpusPerRun',dpu,5,10],['input-component-'+component+'-averageDurationMinutes','SKIP',60,120]);}
// RDS storage-hours is only varied with a valid shorter compute duration.
plans.rds.fields=plans.rds.fields.filter(f=>!f[0].endsWith('storageHours'));
plans.rds.setup=(async original=>async()=>{await original();await inputLocal('input-component-storage-usageMode','capacity');})(plans.rds.setup);
if(process.argv[5]==='serverless'){plans.redshift={url:'redshift',profile:'serverless',fields:[['input-component-serverless-compute-runtimeDailyHours','Expected daily runtime (hours) Enter number of hours',1,2],['input-component-serverless-compute-baseRpu','SELECT:Base RPU',128,256],['input-component-backup-serverless-backupGb','Additional backup storage Value',100,200],['input-component-rms-serverless-managedGb','Managed storage size Value',100,200]],setup:async()=>{await aws.getByRole('radio',{name:'Redshift Serverless',exact:true}).check();}};}
"""
s=s.replace(anchor,extra+'\n'+anchor)
s=s.replace("['strong','windows','selectors'].includes(process.argv[5])?", "['strong','windows','selectors','serverless'].includes(process.argv[5])?")
p.write_text(s)
